import logging
from functools import wraps

logging.basicConfig(level=logging.WARNING, format="%(levelname)s:%(message)s")
logger = logging.getLogger(__name__)

DEPRECATION_MESSAGE = (
    "The function {keyword_name} is deprecated from the API end and will no longer be maintained. "
    "Consider avoiding its use or contact support if required."
)


def deprecated(message=None):
    """This is a decorator which can be used to mark functions as deprecated.
    It will result in a warning being logged when the function is used.
    Optionally, a custom deprecation message can be provided."""

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            warn_msg = message or DEPRECATION_MESSAGE.format(keyword_name=func.__name__)
            logger.warning(warn_msg)
            return func(*args, **kwargs)

        return wrapper

    return decorator
